def render_plan(plan: SchedulePlan) -> str:
    """Return the deterministic text form described in the module docstring."""

    lines = [f"plan {plan.status} makespan={plan.makespan}"]
    for task in plan.tasks:
        resources = ",".join(
            f"{name}={int(task.units[name])}" for name in sorted(task.units)
        )
        lines.append(f"{task.start:04d}-{task.end:04d} {task.task_id} {resources or '-'}")
    blocked_ids = sorted(item.task_id for item in plan.unschedulable)
    if blocked_ids:
        lines.append("unschedulable " + ",".join(blocked_ids))
    return "\n".join(lines) + "\n"

